package com.clavis.reader;
import android.app.Instrumentation;import android.os.SystemClock;
final class NeuralChecks {
 static String run(Instrumentation test)throws Exception{android.content.Context c=test.getTargetContext();long start=SystemClock.elapsedRealtime();NeuralVoice voice=new NeuralVoice(NeuralModel.root(c));try{android.util.Log.i("NeuralChecks","Loaded Hugo in "+(SystemClock.elapsedRealtime()-start)+" ms");long then=SystemClock.elapsedRealtime();short[] pcm=voice.generate("Good evening. This is Hugo, your American narrator. A sentence ends here. The next paragraph starts naturally.");int peak=0;for(short sample:pcm)peak=Math.max(peak,Math.abs((int)sample));if(pcm.length<24000||peak<100)throw new AssertionError("Neural audio is empty or silent");android.util.Log.i("NeuralChecks","Generated "+pcm.length+" samples in "+(SystemClock.elapsedRealtime()-then)+" ms");short[] female=voice.generateWithVoice("Hello. This is original voice, your narrator.",.9f,1);wav(new java.io.File(c.getExternalFilesDir(null),"voice-review-hugo.wav"),pcm,voice.getSampleRate());wav(new java.io.File(c.getExternalFilesDir(null),"voice-review-original.wav"),female,voice.getSampleRate());if(female.length<24000)throw new AssertionError("Female narrator produced no audio");pause(pcm,voice.getSampleRate(),450);pause(voice.generate("A paragraph ends here.\n\n"),voice.getSampleRate(),900);pause(voice.generate("Chapter IV"),voice.getSampleRate(),1200);return "Hugo and original voices, sentence, paragraph and chapter pauses passed. Hugo neural synthesis passed: "+pcm.length+" PCM samples; peak "+peak+"; generation "+(SystemClock.elapsedRealtime()-then)+" ms\n";}finally{voice.release();}}
 static void wav(java.io.File file,short[] pcm,int rate)throws Exception{try(java.io.DataOutputStream out=new java.io.DataOutputStream(new java.io.FileOutputStream(file))){out.writeBytes("RIFF");out.writeInt(Integer.reverseBytes(36+pcm.length*2));out.writeBytes("WAVEfmt ");out.writeInt(Integer.reverseBytes(16));out.writeShort(Short.reverseBytes((short)1));out.writeShort(Short.reverseBytes((short)1));out.writeInt(Integer.reverseBytes(rate));out.writeInt(Integer.reverseBytes(rate*2));out.writeShort(Short.reverseBytes((short)2));out.writeShort(Short.reverseBytes((short)16));out.writeBytes("data");out.writeInt(Integer.reverseBytes(pcm.length*2));for(short sample:pcm)out.writeShort(Short.reverseBytes(sample));}}
 static void pause(short[] pcm,int rate,int ms){int tail=0;for(int n=pcm.length-1;n>=0&&Math.abs((int)pcm[n])<=99;n--)tail++;if(tail<rate*ms/1000-2)throw new AssertionError("Expected at least "+ms+" ms pause, found "+(tail*1000L/rate));}
}
